      })}
      <div style={{display: "flex", gap: 14, marginTop: 26}}>
        {[1, 2, 3].map((n, i) => {
          const s = interpolate(frame, [delay + 50 + i * 10, delay + 62 + i * 10], [0, 1], clamp);
