const STEPS = ["Proposition", "Validation humaine", "Application", "Rollback"];
const XS = [330, 750, 1170, 1590];
const LY = 520;
const FACTS = ["Aucune suppression définitive", "Aucune écriture hors racine", "Aucun écrasement silencieux"];

